import React, { createContext, useContext, useState } from 'react';
import { authAPI } from '../services/api';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    try { return JSON.parse(localStorage.getItem('d2d_user')); } catch { return null; }
  });

  const login = async (phone, pin) => {
    const cleaned = phone.replace(/\D/g, '').slice(-10);
    const res = await authAPI.login({ phone: cleaned, pin });
    const { token, user } = res.data;
    localStorage.setItem('d2d_token', token);
    localStorage.setItem('d2d_user', JSON.stringify(user));
    setUser(user);
    return user;
  };

  const register = async (name, phone, email) => {
    const cleaned = phone.replace(/\D/g, '').slice(-10);
    const res = await authAPI.register({ name, phone: cleaned, email });
    const { token, user } = res.data;
    localStorage.setItem('d2d_token', token);
    localStorage.setItem('d2d_user', JSON.stringify(user));
    setUser(user);
    return user;
  };

  const logout = () => {
    localStorage.removeItem('d2d_token');
    localStorage.removeItem('d2d_user');
    setUser(null);
  };

  const updateUser = (updated) => {
    const merged = { ...user, ...updated };
    localStorage.setItem('d2d_user', JSON.stringify(merged));
    setUser(merged);
  };

  return (
    <AuthContext.Provider value={{ user, login, register, logout, updateUser, isAdmin: user?.role === 'admin' }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
